// Route refresh result to appropriate path
const result = $input.first().json;
const status = result.status;

// Log the result
const logMessage = status === 'updated'
  ? `New data fetched. Dataset updated to ${result.new_timestamp}. Duration: ${result.duration_seconds}s. Records: model=${result.records?.model}, argo=${result.records?.argo}, collocated=${result.records?.collocated}, anomalies=${result.records?.anomalies}`
  : status === 'no_new_data'
  ? `No new data available. Current dataset: ${result.dataset_timestamp}. Duration: ${result.duration_seconds}s`
  : `Refresh error: ${result.message}. Duration: ${result.duration_seconds}s`;

return [{
  json: {
    ...result,
    log_message: logMessage,
    is_updated: status === 'updated',
    is_no_new_data: status === 'no_new_data',
    is_error: status === 'error'
  }
}];

const result = $input.first().json;
return [{
  json: {
    error: 'refresh_failed',
    message: result.message || 'Live data refresh failed',
    status: result.status,
    checked_at: result.checked_at,
    duration_seconds: result.duration_seconds,
    timestamp: new Date().toISOString()
  }
}];

// Validate numerical model data from Ocean Sentry backend
const items = $input.all();
const rawData = items[0].json;

// The backend returns an array of records
const records = Array.isArray(rawData) ? rawData : [rawData];

const valid = [];
const invalid = [];

for (const record of records) {
  const issues = [];

  // Check required coordinate fields
  if (record.latitude === undefined || record.latitude === null) {
    issues.push('missing_latitude');
  } else if (record.latitude < -90 || record.latitude > 90) {
    issues.push('invalid_latitude');
  }

  if (record.longitude === undefined || record.longitude === null) {
    issues.push('missing_longitude');
  } else if (record.longitude < -180 || record.longitude > 360) {
    issues.push('invalid_longitude');
  }

  // Check depth
  if (record.depth !== undefined && record.depth !== null) {
    if (record.depth < 0 || record.depth > 11000) {
      issues.push('invalid_depth');
    }
  }

  // Check timestamp
  if (record.timestamp === undefined || record.timestamp === null) {
    issues.push('missing_timestamp');
  } else {
    const ts = new Date(record.timestamp);
    if (isNaN(ts.getTime())) {
      issues.push('invalid_timestamp');
    }
  }

  // Check model has at least one ocean variable
  const hasTemp = record.model_temperature !== undefined && record.model_temperature !== null;
  const hasSal = record.model_salinity !== undefined && record.model_salinity !== null;
  const hasCurrU = record.model_current_u !== undefined && record.model_current_u !== null;
  const hasCurrV = record.model_current_v !== undefined && record.model_current_v !== null;

  if (!hasTemp && !hasSal && !hasCurrU && !hasCurrV) {
    issues.push('no_model_variables');
  }

  // Temperature range check (GTSPP bounds)
  if (hasTemp && (record.model_temperature < -2.5 || record.model_temperature > 40.0)) {
    issues.push('model_temperature_out_of_range');
  }

  // Salinity range check
  if (hasSal && (record.model_salinity < 2.0 || record.model_salinity > 41.0)) {
    issues.push('model_salinity_out_of_range');
  }

  if (issues.length === 0) {
    valid.push(record);
  } else {
    invalid.push({ record, issues });
  }
}

return [{
  json: {
    source: 'numerical_model',
    data_provider: 'Copernicus Marine (GLOBAL_ANALYSISFORECAST_PHY_001_024)',
    region: 'Bay of Bengal',
    total_received: records.length,
    valid_count: valid.length,
    invalid_count: invalid.length,
    validation_timestamp: new Date().toISOString(),
    records: valid,
    validation_issues: invalid.length > 0 ? invalid.slice(0, 5) : []
  }
}];

// Validate Argo observation data from Ocean Sentry backend
const items = $input.all();
const rawData = items[0].json;

const records = Array.isArray(rawData) ? rawData : [rawData];

const valid = [];
const invalid = [];

for (const record of records) {
  const issues = [];

  // Check required coordinate fields
  if (record.latitude === undefined || record.latitude === null) {
    issues.push('missing_latitude');
  } else if (record.latitude < -90 || record.latitude > 90) {
    issues.push('invalid_latitude');
  }

  if (record.longitude === undefined || record.longitude === null) {
    issues.push('missing_longitude');
  } else if (record.longitude < -180 || record.longitude > 360) {
    issues.push('invalid_longitude');
  }

  // Check depth (Argo profiles can be 0-2000m)
  if (record.depth !== undefined && record.depth !== null) {
    if (record.depth < 0 || record.depth > 6000) {
      issues.push('invalid_depth');
    }
  }

  // Check timestamp
  if (record.timestamp === undefined || record.timestamp === null) {
    issues.push('missing_timestamp');
  } else {
    const ts = new Date(record.timestamp);
    if (isNaN(ts.getTime())) {
      issues.push('invalid_timestamp');
    }
  }

  // Check observation has at least one measurement
  const hasTemp = record.observed_temperature !== undefined && record.observed_temperature !== null;
  const hasSal = record.observed_salinity !== undefined && record.observed_salinity !== null;

  if (!hasTemp && !hasSal) {
    issues.push('no_observation_variables');
  }

  // Temperature range check
  if (hasTemp && (record.observed_temperature < -2.5 || record.observed_temperature > 40.0)) {
    issues.push('observed_temperature_out_of_range');
  }

  // Salinity range check
  if (hasSal && (record.observed_salinity < 2.0 || record.observed_salinity > 41.0)) {
    issues.push('observed_salinity_out_of_range');
  }

  // Check QC flag if available (quality_flag = 1 means passed backend QC)
  if (record.observation_quality !== undefined && record.observation_quality === 4) {
    issues.push('qc_flag_bad');
  }

  if (issues.length === 0) {
    valid.push(record);
  } else {
    invalid.push({ record, issues });
  }
}

return [{
  json: {
    source: 'argo_observations',
    data_provider: 'ArgoVis API (real Argo float profiles)',
    region: 'Bay of Bengal',
    total_received: records.length,
    valid_count: valid.length,
    invalid_count: invalid.length,
    validation_timestamp: new Date().toISOString(),
    records: valid,
    validation_issues: invalid.length > 0 ? invalid.slice(0, 5) : []
  }
}];

// Normalize model data into the common integration schema
const input = $input.first().json;
const records = input.records || [];

const normalized = records.map(r => ({
  source: 'model',
  source_product: 'Copernicus Marine GLOBAL_ANALYSISFORECAST_PHY_001_024',
  latitude: r.latitude,
  longitude: r.longitude,
  depth: r.depth || 0,
  timestamp: r.timestamp,
  temperature: r.model_temperature ?? null,
  salinity: r.model_salinity ?? null,
  current_u: r.model_current_u ?? null,
  current_v: r.model_current_v ?? null,
  sea_level: r.model_sea_level ?? null,
  qc_status: 'model_output'
}));

return [{
  json: {
    source: 'model',
    record_count: normalized.length,
    schema_version: '1.0',
    normalized_at: new Date().toISOString(),
    records: normalized
  }
}];

// Normalize Argo observation data into the common integration schema
const input = $input.first().json;
const records = input.records || [];

const normalized = records.map(r => ({
  source: 'argo',
  source_product: 'ArgoVis - Real Argo Float Profiles',
  latitude: r.latitude,
  longitude: r.longitude,
  depth: r.depth || 0,
  timestamp: r.timestamp,
  temperature: r.observed_temperature ?? null,
  salinity: r.observed_salinity ?? null,
  current_u: null,
  current_v: null,
  sea_level: null,
  qc_status: r.observation_quality === 1 ? 'qc_passed' : 'unverified',
  spatial_distance_km: r.spatial_distance_km ?? null
}));

return [{
  json: {
    source: 'argo',
    record_count: normalized.length,
    schema_version: '1.0',
    normalized_at: new Date().toISOString(),
    records: normalized
  }
}];

// Spatial filtering: keep only records within the Bay of Bengal focus region
// This region matches the backend's Copernicus data bounding box
const items = $input.all();

// Bay of Bengal focus region (matches backend data)
const REGION = {
  lat_min: 5.0,
  lat_max: 18.0,
  lon_min: 80.0,
  lon_max: 92.0
};

let modelRecords = [];
let argoRecords = [];
let totalInput = 0;
let filteredOut = 0;

for (const item of items) {
  const data = item.json;
  const records = data.records || [];
  totalInput += records.length;

  for (const r of records) {
    const inRegion = (
      r.latitude >= REGION.lat_min &&
      r.latitude <= REGION.lat_max &&
      r.longitude >= REGION.lon_min &&
      r.longitude <= REGION.lon_max
    );

    if (inRegion) {
      if (r.source === 'model') {
        modelRecords.push(r);
      } else {
        argoRecords.push(r);
      }
    } else {
      filteredOut++;
    }
  }
}

return [{
  json: {
    stage: 'spatial_filtering',
    region: REGION,
    region_name: 'Bay of Bengal',
    total_input: totalInput,
    total_in_region: modelRecords.length + argoRecords.length,
    filtered_out: filteredOut,
    model_records: modelRecords.length,
    argo_records: argoRecords.length,
    filter_timestamp: new Date().toISOString(),
    model_data: modelRecords,
    argo_data: argoRecords
  }
}];

// Temporal matching: only retain records within a reasonable time window
const input = $input.first().json;
const modelData = input.model_data || [];
const argoData = input.argo_data || [];

const TIME_TOLERANCE_HOURS = 12;

const modelTimes = modelData
  .map(r => new Date(r.timestamp).getTime())
  .filter(t => !isNaN(t));

if (modelTimes.length === 0) {
  return [{
    json: {
      stage: 'temporal_matching',
      error: 'no_model_timestamps',
      message: 'No valid model timestamps found',
      model_count: 0,
      argo_count: 0,
      matched_argo: [],
      model_data: []
    }
  }];
}

const modelTimeMin = Math.min(...modelTimes);
const modelTimeMax = Math.max(...modelTimes);
const toleranceMs = TIME_TOLERANCE_HOURS * 3600 * 1000;

const timeMatchedArgo = [];
const timeUnmatched = [];

for (const argo of argoData) {
  const argoTime = new Date(argo.timestamp).getTime();
  if (isNaN(argoTime)) {
    timeUnmatched.push({ record: argo, reason: 'invalid_timestamp' });
    continue;
  }

  if (argoTime >= (modelTimeMin - toleranceMs) && argoTime <= (modelTimeMax + toleranceMs)) {
    timeMatchedArgo.push(argo);
  } else {
    timeUnmatched.push({ record: argo, reason: 'outside_model_time_window' });
  }
}

return [{
  json: {
    stage: 'temporal_matching',
    time_tolerance_hours: TIME_TOLERANCE_HOURS,
    model_time_range: {
      start: new Date(modelTimeMin).toISOString(),
      end: new Date(modelTimeMax).toISOString()
    },
    model_count: modelData.length,
    argo_input: argoData.length,
    argo_time_matched: timeMatchedArgo.length,
    argo_time_unmatched: timeUnmatched.length,
    match_timestamp: new Date().toISOString(),
    model_data: modelData,
    matched_argo: timeMatchedArgo
  }
}];

// Spatial matching: pair each Argo observation with the nearest model grid point
const input = $input.first().json;
const modelData = input.model_data || [];
const argoData = input.matched_argo || [];

const MAX_DISTANCE_KM = 50.0;

function haversine(lat1, lon1, lat2, lon2) {
  const R = 6371.0;
  const dLat = (lat2 - lat1) * Math.PI / 180;
  const dLon = (lon2 - lon1) * Math.PI / 180;
  const a = Math.sin(dLat / 2) ** 2 +
    Math.cos(lat1 * Math.PI / 180) * Math.cos(lat2 * Math.PI / 180) *
    Math.sin(dLon / 2) ** 2;
  return R * 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));
}

const matched = [];
const unmatched = [];

for (const argo of argoData) {
  let bestModel = null;
  let bestDist = Infinity;

  for (const model of modelData) {
    if (Math.abs(model.latitude - argo.latitude) > 0.5 ||
        Math.abs(model.longitude - argo.longitude) > 0.5) {
      continue;
    }

    const dist = haversine(argo.latitude, argo.longitude, model.latitude, model.longitude);
    if (dist < bestDist) {
      bestDist = dist;
      bestModel = model;
    }
  }

  if (bestModel !== null && bestDist <= MAX_DISTANCE_KM) {
    matched.push({
      argo: argo,
      model: bestModel,
      spatial_distance_km: Math.round(bestDist * 100) / 100
    });
  } else {
    unmatched.push({
      argo_lat: argo.latitude,
      argo_lon: argo.longitude,
      nearest_distance_km: bestDist === Infinity ? null : Math.round(bestDist * 100) / 100,
      reason: bestDist === Infinity ? 'no_model_nearby' : 'exceeds_max_distance'
    });
  }
}

return [{
  json: {
    stage: 'spatial_matching',
    max_distance_km: MAX_DISTANCE_KM,
    model_points_available: modelData.length,
    argo_input: argoData.length,
    spatially_matched: matched.length,
    spatially_unmatched: unmatched.length,
    match_timestamp: new Date().toISOString(),
    pairs: matched
  }
}];

// Compare model predictions against real Argo observations
const input = $input.first().json;
const pairs = input.pairs || [];

if (pairs.length === 0) {
  return [{
    json: {
      stage: 'model_observation_comparison',
      error: 'no_matched_pairs',
      message: 'No spatially matched model-observation pairs available',
      comparisons: [],
      summary: { total: 0 }
    }
  }];
}

const comparisons = [];

for (const pair of pairs) {
  const model = pair.model;
  const argo = pair.argo;

  const comparison = {
    latitude: argo.latitude,
    longitude: argo.longitude,
    depth: argo.depth,
    timestamp: argo.timestamp,
    spatial_distance_km: pair.spatial_distance_km,
    parameters: []
  };

  if (model.temperature !== null && argo.temperature !== null) {
    const diff = argo.temperature - model.temperature;
    comparison.parameters.push({
      parameter: 'temperature',
      unit: '°C',
      model_value: model.temperature,
      observed_value: argo.temperature,
      difference: Math.round(diff * 1000) / 1000,
      absolute_difference: Math.round(Math.abs(diff) * 1000) / 1000,
      observation_source: 'Argo'
    });
  }

  if (model.salinity !== null && argo.salinity !== null) {
    const diff = argo.salinity - model.salinity;
    comparison.parameters.push({
      parameter: 'salinity',
      unit: 'PSU',
      model_value: model.salinity,
      observed_value: argo.salinity,
      difference: Math.round(diff * 1000) / 1000,
      absolute_difference: Math.round(Math.abs(diff) * 1000) / 1000,
      observation_source: 'Argo'
    });
  }

  if (comparison.parameters.length > 0) {
    comparisons.push(comparison);
  }
}

const tempDiffs = comparisons
  .flatMap(c => c.parameters)
  .filter(p => p.parameter === 'temperature')
  .map(p => p.absolute_difference);

const salDiffs = comparisons
  .flatMap(c => c.parameters)
  .filter(p => p.parameter === 'salinity')
  .map(p => p.absolute_difference);

function stats(arr) {
  if (arr.length === 0) return null;
  const sorted = [...arr].sort((a, b) => a - b);
  return {
    count: arr.length,
    min: sorted[0],
    max: sorted[sorted.length - 1],
    mean: Math.round(arr.reduce((a, b) => a + b, 0) / arr.length * 1000) / 1000,
    median: sorted[Math.floor(sorted.length / 2)]
  };
}

return [{
  json: {
    stage: 'model_observation_comparison',
    total_pairs: pairs.length,
    comparisons_produced: comparisons.length,
    comparison_timestamp: new Date().toISOString(),
    summary: {
      temperature: stats(tempDiffs),
      salinity: stats(salDiffs)
    },
    comparisons: comparisons
  }
}];

// Deviation detection and quality flagging
const input = $input.first().json;
const comparisons = input.comparisons || [];

const THRESHOLDS = {
  temperature: { warning: 1.5, high: 2.5 },
  salinity: { warning: 0.8, high: 1.5 }
};

const flagged = [];
const normal = [];

for (const comp of comparisons) {
  let maxStatus = 'normal';
  const flaggedParams = [];

  for (const param of comp.parameters) {
    const thresholds = THRESHOLDS[param.parameter];
    if (!thresholds) continue;

    let paramStatus = 'normal';
    if (param.absolute_difference >= thresholds.high) {
      paramStatus = 'significant_deviation';
    } else if (param.absolute_difference >= thresholds.warning) {
      paramStatus = 'warning';
    }

    param.deviation_status = paramStatus;
    param.threshold_used = thresholds;

    if (paramStatus === 'significant_deviation') {
      maxStatus = 'significant_deviation';
      flaggedParams.push(param.parameter);
    } else if (paramStatus === 'warning' && maxStatus !== 'significant_deviation') {
      maxStatus = 'warning';
      flaggedParams.push(param.parameter);
    }
  }

  comp.overall_status = maxStatus;
  comp.flagged_parameters = flaggedParams;

  if (maxStatus === 'normal') {
    normal.push(comp);
  } else {
    flagged.push(comp);
  }
}

return [{
  json: {
    stage: 'deviation_qc',
    thresholds: THRESHOLDS,
    total_comparisons: comparisons.length,
    normal_count: normal.length,
    warning_count: flagged.filter(f => f.overall_status === 'warning').length,
    significant_deviation_count: flagged.filter(f => f.overall_status === 'significant_deviation').length,
    qc_timestamp: new Date().toISOString(),
    all_comparisons: comparisons,
    flagged_records: flagged,
    normal_records: normal
  }
}];

// Prepare the final dataset for the 3D visualization frontend
const input = $input.first().json;
const allComparisons = input.all_comparisons || [];

const visualizationRecords = [];

for (const comp of allComparisons) {
  for (const param of comp.parameters) {
    visualizationRecords.push({
      type: 'observation',
      location: {
        latitude: comp.latitude,
        longitude: comp.longitude
      },
      depth: comp.depth,
      timestamp: comp.timestamp,
      parameter: param.parameter,
      unit: param.unit,
      value: param.observed_value,
      source: 'argo',
      status: comp.overall_status,
      comparison: {
        model_value: param.model_value,
        observed_value: param.observed_value,
        difference: param.difference,
        absolute_difference: param.absolute_difference,
        deviation_status: param.deviation_status
      },
      metadata: {
        spatial_distance_km: comp.spatial_distance_km,
        processing_timestamp: new Date().toISOString(),
        pipeline: 'n8n_ocean_data_integration'
      }
    });
  }
}

const depthRange = visualizationRecords.length > 0 ? {
  min: Math.min(...visualizationRecords.map(r => r.depth)),
  max: Math.max(...visualizationRecords.map(r => r.depth))
} : { min: 0, max: 0 };

const uniqueLocations = new Set(
  visualizationRecords.map(r => `${r.location.latitude},${r.location.longitude}`)
).size;

return [{
  json: {
    stage: 'visualization_dataset',
    dataset_version: '1.0',
    pipeline: 'Ocean Sentry n8n Data Integration',
    total_records: visualizationRecords.length,
    unique_locations: uniqueLocations,
    depth_range: depthRange,
    parameters: [...new Set(visualizationRecords.map(r => r.parameter))],
    status_distribution: {
      normal: visualizationRecords.filter(r => r.status === 'normal').length,
      warning: visualizationRecords.filter(r => r.status === 'warning').length,
      significant_deviation: visualizationRecords.filter(r => r.status === 'significant_deviation').length
    },
    prepared_at: new Date().toISOString(),
    records: visualizationRecords
  }
}];

// Final pipeline report: combines live refresh, n8n processing, and backend verification
const refreshResult = $('Process Refresh Result').first().json;
const n8nData = $('Prepare 3D Dataset').first().json;
const dataStatus = $input.first().json;

return [{
  json: {
    pipeline_report: {
      name: 'Ocean Sentry — Core Data Integration Pipeline',
      purpose: 'Automated near-real-time data refresh with model-observation integration for 3D visualization',
      completed_at: new Date().toISOString(),
      status: 'success'
    },
    live_refresh: {
      outcome: refreshResult.status,
      duration_seconds: refreshResult.duration_seconds,
      message: refreshResult.log_message,
      previous_timestamp: refreshResult.previous_timestamp || null,
      new_timestamp: refreshResult.new_timestamp || refreshResult.dataset_timestamp || null,
      records_updated: refreshResult.records || null
    },
    data_sources: {
      numerical_model: {
        provider: 'Copernicus Marine Service',
        product: 'GLOBAL_ANALYSISFORECAST_PHY_001_024',
        variables: ['temperature', 'salinity', 'current_u', 'current_v'],
        region: 'Bay of Bengal (5-18\u00b0N, 80-92\u00b0E)'
      },
      in_situ_observations: {
        provider: 'Argo Program (via ArgoVis API)',
        variables: ['temperature', 'salinity'],
        qc_applied: true,
        region: 'Bay of Bengal'
      }
    },
    integration_summary: {
      total_visualization_records: n8nData.total_records,
      unique_locations: n8nData.unique_locations,
      depth_range_m: n8nData.depth_range,
      parameters_compared: n8nData.parameters,
      status_distribution: n8nData.status_distribution
    },
    backend_verification: {
      data_status: dataStatus.status,
      last_refresh: dataStatus.last_refresh_timestamp,
      total_records: dataStatus.total_records,
      anomaly_count: dataStatus.anomaly_count,
      data_source: dataStatus.data_source,
      data_window: dataStatus.data_window
    },
    pipeline_parameters: {
      refresh_interval_hours: 6,
      spatial_tolerance_km: 50,
      temporal_tolerance_hours: 12,
      temperature_warning_threshold_C: 1.5,
      temperature_deviation_threshold_C: 2.5,
      salinity_warning_threshold_PSU: 0.8,
      salinity_deviation_threshold_PSU: 1.5
    },
    architecture_note: 'Every six hours, n8n triggers the refresh service. The refresh service performs a lightweight metadata check against Copernicus. If no newer dataset is available, the pipeline exits without downloading. If newer data is available, it fetches the latest model and Argo observations, performs QC, spatial-temporal collocation and ML anomaly scoring, then atomically updates the datasets served by FastAPI. The 3D frontend automatically reads the refreshed data through the same APIs.'
  }
}];
